        s *= 0.55 + 0.45 * sin(time * (1.5 + r * 3.0) + r * 90.0);
        c += vec3(s) * stars * smoothstep(-0.02, 0.2, h) * mix(vec3(1.0), vec3(1.0, 0.85, 0.7), step(0.993, r));
